## Why This Is Asked
This tests fixed-length path DP and path reconstruction in graphs, a core DP pattern that shows depth beyond standard knapsack.

## Key Concepts
- DP on path length t
- State transition using edges
- Backpointer reconstruction
- Time and space trade-offs

## Code Example
```javascript
function maxKEdgePath(n, edges, k) {
  const NEG = -Infinity;
  const dp = Array.from({length: n}, () => Array(k+1).fill(NEG));
  const par = Array.from({length: n}, () => Array(k+1).fill(-1));
  for (let v=0; v<n; v++) dp[v][0] = 0;
  for (let t=1; t<=k; t++) {
    for (const e of edges) {
      const {u,v,w} = e;
      const prev = dp[u][t-1];
      if (prev !== NEG) {
        const cand = prev + w;
        if (cand > dp[v][t]) {
          dp[v][t] = cand;
          par[v][t] = u;
        }
      }
    }
  }
  let bestV = 0, best = NEG;
  for (let v=0; v<n; v++) if (dp[v][k] > best) { best = dp[v][k]; bestV = v; }
  const path = [];
  let cur = bestV;
  for (let t=k; t>=1; t--) { path.push(cur); cur = par[cur][t]; }
  path.push(cur);
  path.reverse();
  return {path, weight: best};
}
```

## Follow-up Questions
- How would this change if edges could have negative weights? How to handle ties in reconstruction?

## Why This Is Asked
Tests DP partitioning with a non-sum objective and reconstruction requirements.

## Key Concepts
- DP over partitions with dp[i][t]
- Precomputing max-min for all subarrays
- Path reconstruction via parent pointers

## Code Example
```javascript
function maxMinSubarrayVal(arr){
  const n = arr.length;
  const maxVal = Array.from({length:n}, ()=>Array(n).fill(0));
  const minVal = Array.from({length:n}, ()=>Array(n).fill(0));
  for(let i=0;i<n;i++){
    let curMax = arr[i], curMin = arr[i];
    for(let j=i;j<n;j++){
      curMax = Math.max(curMax, arr[j]);
      curMin = Math.min(curMin, arr[j]);
      maxVal[i][j] = curMax;
      minVal[i][j] = curMin;
    }
  }
  const val = (l,r)=> maxVal[l][r] - minVal[l][r];
  return val;
}

function bestPartition(arr, k){
  const n = arr.length;
  const val = maxMinSubarrayVal(arr);
  const dp = Array.from({length:n+1}, ()=>Array(k+1).fill(-Infinity));
  const parent = Array.from({length:n+1}, ()=>Array(k+1).fill(-1));
  for(let i=1;i<=n;i++) dp[i][1] = val(0,i-1);
  for(let t=2;t<=k;t++){
    for(let i=t;i<=n;i++){
      for(let j=t-1;j<=i-1;j++){
        const cand = dp[j][t-1] + val(j, i-1);
        if(cand > dp[i][t]){ dp[i][t] = cand; parent[i][t]=j; }
      }
    }
  }
  // reconstruct
  let blocks = [];
  let i=n, t=k;
  while(t>0){
    const j = parent[i][t];
    blocks.push([j, i-1]);
    i = j; t--;
  }
  blocks.reverse();
  return {value: dp[n][k], blocks};
}
```

## Follow-up Questions
- How to optimize memory to O(nk)?
- Can you handle ties deterministically for block reconstruction?

## Why This Is Asked

Tests DP formulation for selecting fixed-count non-overlapping subarrays with a per-block cost, plus reconstruction of blocks.

## Key Concepts

- DP over i (prefix) and t (blocks)
- Prefix sums for subarray sums
- Running best to avoid O(n^2)
- Reconstructing start/end indices

## Code Example

```javascript
function maxKSubarraysWithCost(A, k, c){
  const n = A.length;
  const pref = new Array(n+1).fill(0);
  for (let i = 0; i < n; i++) pref[i+1] = pref[i] + A[i];
  const NEG = -1e15;
  const dp = Array.from({length: n+1}, () => new Array(k+1).fill(NEG));
  const from = Array.from({length: n+1}, () => new Array(k+1).fill(null));
  dp[0][0] = 0;
  const bestVal = new Array(k+1).fill(NEG);
  const bestIdx = new Array(k+1).fill(-1);
  for (let i = 1; i <= n; i++){
    for (let t = 0; t <= k; t++){
      dp[i][t] = dp[i-1][t];
      from[i][t] = {type:'skip', at:i-1, t};
    }
    for (let t = 1; t <= k; t++){
      const val = dp[i-1][t-1] - pref[i-1];
      if (val > bestVal[t]) { bestVal[t] = val; bestIdx[t] = i-1; }
      const cand = bestVal[t] + pref[i] - c;
      if (cand > dp[i][t]) {
        dp[i][t] = cand;
        from[i][t] = {type:'end', end:i-1, start:bestIdx[t], t};
      }
    }
  }
  let i = n, t = k;
  const blocks = [];
  while (i > 0 && t > 0){
    const info = from[i][t];
    if (!info) break;
    if (info.type === 'end'){
      blocks.push([info.start, info.end]);
      i = info.start;
      t--;
    } else {
      i = info.at;
    }
  }
  blocks.reverse();
  return { value: dp[n][k], blocks };
}
```

## Follow-up Questions

- How would you adapt for at-most-k blocks?
- How would you handle negative values of c or allow zero-cost blocks?
- What modifications optimize space to O(k) while preserving reconstruction?

## Why This Is Asked
Tests concrete DP skills on string partitioning with reconstruction; approachable for beginners yet non-trivial.

## Key Concepts
- dp[i][t]: maximum sum for first i digits split into t parts
- val(j,i): integer value of s[j..i-1] (leading zeros allowed)
- transition: dp[i][t] = max_{j ∈ [t-1..i-1]} dp[j][t-1] + val(j,i)
- reconstruction: track prev to recover split indices
- complexity: O(n²k) time, O(nk) space; use BigInt for large results

## Code Example
```javascript
function maxSumSplit(s, k){
  const n = s.length;
  const val = (a,b)=> BigInt(s.slice(a,b));
  const dp = Array.from({length: n+1}, () => Array(k+1).fill(-1n));
  const prev = Array.from({length: n+1}, () => Array(k+1).fill(-1));

  for(let i=1;i<=n;i++){
    dp[i][1] = val(0,i);
  }

  for(let t=2;t<=k;t++){
    for(let i=t;i<=n;i++){
      for(let j=t-1;j<i;j++){
        const candidate = dp[j][t-1] + val(j,i);
        if(candidate > dp[i][t]){
          dp[i][t] = candidate;
          prev[i][t] = j;
        }
      }
    }
  }

  // Reconstruct splits
  const splits = [];
  let curr = n, parts = k;
  while(parts > 1){
    const j = prev[curr][parts];
    splits.push(j);
    curr = j;
    parts--;
  }
  splits.reverse();

  return {maxSum: dp[n][k], splits};
}
```

## Why This Is Asked
Tests DP design for selecting multiple disjoint subarrays with reconstruction. Requires prefix sums, state definition, and backtracking.

## Key Concepts
- DP over positions and count of subarrays
- Prefix sums for subarray sums
- Reconstructing intervals with predecessor pointers
- Time/space trade-offs (O(nk) vs optimizations)

## Code Example
```javascript
function maxKSubarrays(A, k) {
  const n = A.length; const P = new Array(n+1).fill(0);
  for (let i=1;i<=n;i++) P[i] = P[i-1] + A[i-1];
  const dp = Array.from({length:n+1}, ()=>new Array(k+1).fill(-Infinity));
  const from = Array.from({length:n+1}, ()=>new Array(k+1).fill(null));
  for (let i=0;i<=n;i++) dp[i][0] = 0;
  for (let t=1;t<=k;t++){
    let best = -Infinity;
    let bestIdx = -1;
    for (let i=1;i<=n;i++){
      if (dp[i-1][t-1] - P[i-1] > best){ best = dp[i-1][t-1] - P[i-1]; bestIdx = i-1; }
      const take = P[i] + best;
      if (take > dp[i-1][t]){ dp[i][t] = take; from[i][t] = [bestIdx+1, i]; }
      else { dp[i][t] = dp[i-1][t]; }
    }
  }
  // reconstruction (omitted for brevity in this snippet)
  return {maxSum: dp[n][k], intervals: []};
}
```

